wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(41374838973430215640)
,p_plug_name=>'INVENTORY DASHBOARD'
,p_static_id=>'inventory-dashboard'
,p_parent_plug_id=>wwv_flow_imp.id(41359912621445851401)
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Total Products'' AS card_title,',
'       TO_CHAR(COUNT(*), ''FM999,999'') AS card_value,',
'       ''fa-box-open'' AS card_icon,',
'       ''u-color-1'' AS card_color,',
'       1 AS display_order',
'  FROM STORE_GROCERIES',
' WHERE status = ''ACTIVE''',
'',
'UNION ALL',
'',
'SELECT ''Active Suppliers'' AS card_title,',
'       TO_CHAR(COUNT(DISTINCT supplier_id), ''FM999,999'') AS card_value,',
'       ''fa-truck'' AS card_icon,',
'       ''u-color-4'' AS card_color,',
'       2 AS display_order',
'  FROM STORE_GROCERIES',
' WHERE status = ''ACTIVE''',
'   AND supplier_id IS NOT NULL',
'',
'UNION ALL',
'',
'SELECT ''Inventory Items'' AS card_title,',
'       TO_CHAR(NVL(SUM(stock_qty), 0), ''FM999,999,990'') AS card_value,',
'       ''fa-boxes'' AS card_icon,',
'       ''u-color-2'' AS card_color,',
'       3 AS display_order',
'  FROM STORE_GROCERIES',
' WHERE status = ''ACTIVE''',
'',
'UNION ALL',
'',
'SELECT ''Low Stock Alert'' AS card_title,',
'       TO_CHAR(COUNT(*), ''FM999,999'') AS card_value,',
'       ''fa-exclamation-triangle'' AS card_icon,',
'       ''u-color-9'' AS card_color,',
'       4 AS display_order',
'  FROM STORE_GROCERIES',
' WHERE stock_qty <= reorder_level',
'   AND status = ''ACTIVE''',
'',
'ORDER BY display_order;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20260925074210Z')
,p_updated_on=>wwv_flow_imp.dz('20260925075810Z')
,p_created_by=>'RVSHRI369@GMAIL.COM'
,p_updated_by=>'RVSHRI369@GMAIL.COM'
);
